import sys

def simulate_drawing(h, w, n, target, commands):
    # Initialize the board and marker position
    board = [['.' for _ in range(w)] for _ in range(h)]
    x, y = h - 1, 0
    timesteps = [[-1] * w for _ in range(h)]
    current_time = 0

    # Execute the commands
    for i, (direction, distance) in enumerate(commands):
        distance = int(distance)
        if direction == 'up':
            for _ in range(distance):
                if board[x][y] == '.':
                    board[x][y] = '#'
                    timesteps[x][y] = current_time
                current_time += 1
                x -= 1
        elif direction == 'down':
            for _ in range(distance):
                if board[x][y] == '.':
                    board[x][y] = '#'
                    timesteps[x][y] = current_time
                current_time += 1
                x += 1
        elif direction == 'left':
            for _ in range(distance):
                if board[x][y] == '.':
                    board[x][y] = '#'
                    timesteps[x][y] = current_time
                current_time += 1
                y -= 1
        elif direction == 'right':
            for _ in range(distance):
                if board[x][y] == '.':
                    board[x][y] = '#'
                    timesteps[x][y] = current_time
                current_time += 1
                y += 1

    # Check if the final board matches the target
    if board != target:
        return -1, -1

    # Find the earliest and latest possible timesteps for the marker to dry out
    min_time = float('inf')
    max_time = float('-inf')

    for i in range(h):
        for j in range(w):
            if target[i][j] == '#':
                min_time = min(min_time, timesteps[i][j])
                max_time = max(max_time, timesteps[i][j])

    return min_time, max_time

