    import sys
    import heapq

    def dijkstra(graph, start, end):
        min_heap = [(0, start)]
        max_heap = [(-0, start)]
        min_dist = {start: 0}
        max_dist = {start: 0}

        while min_heap:
            min_d, u = heapq.heappop(min_heap)
            if u == end:
                break
            for v, weight in graph[u]:
                if v not in min_dist or min_dist[v] > min_d + weight:
                    min_dist[v] = min_d + weight
                    heapq.heappush(min_heap, (min_d + weight, v))

        while max_heap:
            max_d, u = heapq.heappop(max_heap)
            if u == end:
                break
            for v, weight in graph[u]:
                if v not in max_dist or max_dist[v] < -max_d + weight:
                    max_dist[v] = -max_d + weight
                    heapq.heappush(max_heap, (-max_d + weight, v))

        return min_dist[end], max_dist[end]

    def get_neighbors(x, y, h, w):
        neighbors = []
        if x > 0:
            neighbors.append((x-1, y))
        if x < h-1:
            neighbors.append((x+1, y))
        if y > 0:
            neighbors.append((x, y-1))
        if y < w-1:
            neighbors.append((x, y+1))
        return neighbors

    def parse_input():
        h, w, n = map(int, sys.stdin.readline().split())
        target = [sys.stdin.readline().strip() for _ in range(h)]
        commands = [sys.stdin.readline().split() for _ in range(n)]
        return h, w, n, target, commands

    def build_graph(h, w, n, target, commands):
        graph = {}
        for i in range(h):
            for j in range(w):
                graph[(i, j)] = []

        x, y = h-1, 0
        for cmd in commands:
            direction, distance = cmd[0], int(cmd[1])
            if direction == 'up':
                for k in range(1, distance+1):
                    nx, ny = x-k, y
                    if target[nx][ny] == '#':
                        graph[(x, y)].append(((nx, ny), k))
                    else:
                        graph[(x, y)].append(((nx, ny), 0))
                    x = nx
            elif direction == 'down':
                for k in range(1, distance+1):
                    nx, ny = x+k, y
                    if target[nx][ny] == '#':
                        graph[(x, y)].append(((nx, ny), k))
                    else:
                        graph[(x, y)].append(((nx, ny), 0))
                    x = nx
            elif direction == 'left':
                for k in range(1, distance+1):
                    nx, ny = x, y-k
                    if target[nx][ny] == '#':
                        graph[(x, y)].append(((nx, ny), k))
                    else:
                        graph[(x, y)].append(((nx, ny), 0))
                    y = ny
            elif direction == 'right':
                for k in range(1, distance+1):
                    nx, ny = x, y+k
                    if target[nx][ny] == '#':
                        graph[(x, y)].append(((nx, ny), k))
                    else:
                        graph[(x, y)].append(((nx, ny), 0))
                    y = ny

        return graph

    h, w, n, target, commands = parse_input()
    graph = build_graph(h, w, n, target, commands)
    min_time, max_time = dijkstra(graph, (h-1, 0), (0, w-1))

    if min_time == float('inf') or max_time == float('inf'):
        print(-1, -1)
    else:
        print(min_time, max_time)

